class EtudeTheme {
  const EtudeTheme({
    required this.genre,
    required this.place,
    required this.situation,
    required this.relationship,
    required this.secret,
    required this.constraint,
    required this.roleKey,
    this.roles = const [],
    this.audited = false,
    this.customReflectionQuestions = const [],
    this.auditNotes = const [],
  });

  final String genre;
  final String place;
  final String situation;
  final String relationship;
  final String secret;
  final String constraint;
  final String roleKey;
  final List<String> roles;
  final bool audited;
  final List<String> customReflectionQuestions;
  final List<String> auditNotes;

  List<String> get reflectionQuestions => customReflectionQuestions.isNotEmpty
      ? customReflectionQuestions
      : [
          '「$situation」という状況が動いたのは、誰のどんな行動から？',
          '「$relationship」という関係は、始まる前と終わった後でどう変わった？',
          '「$constraint」という制約は、物語や演技にどんな影響を与えた？',
        ];
}

